import{_ as d,o as e,c as o,ah as r}from"./chunks/framework.CWPz2Xm4.js";const u=JSON.parse('{"title":"Data dictionary","description":"","frontmatter":{"outline":[2,2]},"headers":[],"relativePath":"data-dictionary.md","filePath":"data-dictionary.md"}'),a={name:"data-dictionary.md"};function s(n,t,c,i,h,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="data-dictionary" tabindex="-1">Data dictionary <a class="header-anchor" href="#data-dictionary" aria-label="Permalink to &quot;Data dictionary&quot;">​</a></h1><p>Generated from the runtime schemas in <code>packages/schemas</code> (DOC-3). Do not edit by hand: run <code>pnpm dictionary</code>.</p><p>Every document carries <code>schemaVersion</code>; clients migrate older versions on read and ignore payloads that fail validation (ARC-6, NFR-5).</p><h2 id="game-setup" tabindex="-1">Game setup <a class="header-anchor" href="#game-setup" aria-label="Permalink to &quot;Game setup&quot;">​</a></h2><p>Game properties and the game theme.</p><ul><li><strong>Location:</strong> PubSub node <code>game-setup</code></li><li><strong>Access:</strong> Read: anyone, including anonymous users. Publish: admin.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 120</td><td>Display name</td></tr><tr><td><code>description</code></td><td>string</td><td>yes</td><td>length ≤ 1000</td><td>Short description</td></tr><tr><td><code>briefing</code></td><td>string</td><td>yes</td><td>length ≤ 20000</td><td>Public Markdown briefing for the welcome page (PLY-46–48)</td></tr><tr><td><code>designVersion</code></td><td>integer</td><td>yes</td><td>≥ 1</td><td>Incremented by a publish that changes the structure: a room added or removed, or the effective access to a room of a role in both designs (§3 rule 8); keys saved layouts (PLY-5)</td></tr><tr><td><code>theme</code></td><td>object</td><td>yes</td><td></td><td>Theme: tokens plus optional logo and icon assets</td></tr><tr><td><code>theme.tokens</code></td><td>object</td><td>yes</td><td></td><td>Design tokens; an unset token inherits from the game theme, then the default</td></tr><tr><td><code>theme.tokens.primary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.secondary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.background</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.surface</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.text</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.fontFamily</code></td><td>enum</td><td>no</td><td>one of &quot;sans&quot;, &quot;serif&quot;, &quot;mono&quot;</td><td>Bundled font id</td></tr><tr><td><code>theme.logoAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr><tr><td><code>theme.iconAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr><tr><td><code>roomTypeDefaults</code></td><td>map of map of any</td><td>yes</td><td></td><td>Default config per room type, validated by that type (ARC-5)</td></tr></tbody></table><h2 id="force" tabindex="-1">Force <a class="header-anchor" href="#force" aria-label="Permalink to &quot;Force&quot;">​</a></h2><p>A side in the game.</p><ul><li><strong>Location:</strong> PubSub node <code>forces:&lt;forceId&gt;</code></li><li><strong>Access:</strong> Read: all game users. Publish: admin.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Entity id: a lowercase GUID, generated at creation, never reused (SRD §3 rule 1)</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 120</td><td>Display name</td></tr><tr><td><code>colour</code></td><td>string</td><td>yes</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour for message authors; not a theme token (§3 rule 13)</td></tr><tr><td><code>iconAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr><tr><td><code>isUmpire</code></td><td>boolean</td><td>yes</td><td></td><td>The umpire flag: this is the White Force, which the admin plays in as umpire; exactly one force has it (ADM-4, D8)</td></tr><tr><td><code>order</code></td><td>integer</td><td>yes</td><td>≥ 0</td><td>Admin-set display order; ties sort by id (SRD §3 rule 7)</td></tr><tr><td><code>theme</code></td><td>object</td><td>no</td><td></td><td>Styles the force panel only (D19)</td></tr><tr><td><code>theme.tokens</code></td><td>object</td><td>yes</td><td></td><td>Design tokens; an unset token inherits from the game theme, then the default</td></tr><tr><td><code>theme.tokens.primary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.secondary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.background</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.surface</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.text</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.fontFamily</code></td><td>enum</td><td>no</td><td>one of &quot;sans&quot;, &quot;serif&quot;, &quot;mono&quot;</td><td>Bundled font id</td></tr><tr><td><code>theme.logoAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr><tr><td><code>theme.iconAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr></tbody></table><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p>A player position; one XMPP account.</p><ul><li><strong>Location:</strong> PubSub node <code>roles:&lt;roleId&gt;</code>; the role is the XMPP account <code>&lt;loginName&gt;@&lt;domain&gt;</code></li><li><strong>Access:</strong> Read: all game users. Publish: admin.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Role id, a GUID</td></tr><tr><td><code>loginName</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 64; pattern <code>^[a-z0-9]+(?:-[a-z0-9]+)*$</code></td><td>Login name: the role&#39;s XMPP account name, readable, fixed once published (§3 rule 1, ADM-5)</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 120</td><td>Display name</td></tr><tr><td><code>forceId</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of the role&#39;s force</td></tr><tr><td><code>isObserver</code></td><td>boolean</td><td>yes</td><td></td><td>Observers read but never post, in all their rooms (D8)</td></tr><tr><td><code>order</code></td><td>integer</td><td>yes</td><td>≥ 0</td><td>Admin-set display order; ties sort by id (SRD §3 rule 7)</td></tr></tbody></table><h2 id="room" tabindex="-1">Room <a class="header-anchor" href="#room" aria-label="Permalink to &quot;Room&quot;">​</a></h2><p>A channel: one MUC room plus this config.</p><ul><li><strong>Location:</strong> PubSub node <code>rooms:&lt;roomId&gt;</code></li><li><strong>Access:</strong> Read: game users. Publish: admin.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Entity id: a lowercase GUID, generated at creation, never reused (SRD §3 rule 1)</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 120</td><td>Display name</td></tr><tr><td><code>roomType</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 64; pattern <code>^[a-z0-9]+(?:-[a-z0-9]+)*$</code></td><td>Room type id from the registry (v1: chat and map)</td></tr><tr><td><code>participants</code></td><td>array of object</td><td>yes</td><td></td><td>Mixed force and role entries; White Force roles are added implicitly, and a role entry assigns a White Force observer the room (§3 rule 4)</td></tr><tr><td><code>participants[]</code></td><td>object</td><td>yes</td><td></td><td>A room participant entry (§3 rule 4)</td></tr><tr><td><code>participants[].kind</code></td><td>enum</td><td>yes</td><td>one of &quot;force&quot;, &quot;role&quot;</td><td></td></tr><tr><td><code>participants[].id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Force or role id</td></tr><tr><td><code>participants[].access</code></td><td>enum</td><td>yes</td><td>one of &quot;write&quot;, &quot;read&quot;</td><td>Read-only entries join as MUC visitors</td></tr><tr><td><code>config</code></td><td>map of any</td><td>yes</td><td></td><td>Type-specific config, validated by the room type (ARC-5)</td></tr><tr><td><code>order</code></td><td>integer</td><td>yes</td><td>≥ 0</td><td>Admin-set display order; ties sort by id (SRD §3 rule 7)</td></tr><tr><td><code>theme</code></td><td>object</td><td>no</td><td></td><td>Styles this room&#39;s panel and tab</td></tr><tr><td><code>theme.tokens</code></td><td>object</td><td>yes</td><td></td><td>Design tokens; an unset token inherits from the game theme, then the default</td></tr><tr><td><code>theme.tokens.primary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.secondary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.background</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.surface</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.text</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>theme.tokens.fontFamily</code></td><td>enum</td><td>no</td><td>one of &quot;sans&quot;, &quot;serif&quot;, &quot;mono&quot;</td><td>Bundled font id</td></tr><tr><td><code>theme.logoAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr><tr><td><code>theme.iconAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr></tbody></table><h2 id="objectives" tabindex="-1">Objectives <a class="header-anchor" href="#objectives" aria-label="Permalink to &quot;Objectives&quot;">​</a></h2><p>A force&#39;s objectives; confidential to that force, the White Force and the admin.</p><ul><li><strong>Location:</strong> PubSub node <code>objectives:&lt;forceId&gt;</code></li><li><strong>Access:</strong> Read: the force&#39;s roles, every White Force role and the admin. Publish: the admin only, as one item (<code>admin</code>) replaced on each edit.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>forceId</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of the force these objectives belong to</td></tr><tr><td><code>markdown</code></td><td>string</td><td>yes</td><td>length ≤ 50000</td><td>Objectives as Markdown</td></tr><tr><td><code>updatedAt</code></td><td>string</td><td>yes</td><td>format date-time</td><td>When the admin wrote this version, by the admin&#39;s clock; display only. The node holds one item, the admin&#39;s, replaced on each edit; a live notification replaces the copy fetched at login, whatever this says (§3 rule 14)</td></tr></tbody></table><h2 id="asset" tabindex="-1">Asset <a class="header-anchor" href="#asset" aria-label="Permalink to &quot;Asset&quot;">​</a></h2><p>An image used by themes.</p><ul><li><strong>Location:</strong> PubSub node <code>assets:&lt;assetId&gt;</code></li><li><strong>Access:</strong> Read: game users; the game theme&#39;s assets also anonymously. Publish: admin.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Entity id: a lowercase GUID, generated at creation, never reused (SRD §3 rule 1)</td></tr><tr><td><code>mimeType</code></td><td>enum</td><td>yes</td><td>one of &quot;image/png&quot;, &quot;image/webp&quot;, &quot;image/svg+xml&quot;</td><td></td></tr><tr><td><code>size</code></td><td>integer</td><td>yes</td><td>≥ 1; ≤ 180000</td><td>Decoded size in bytes</td></tr><tr><td><code>sha256</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{64}$</code></td><td>SHA-256 of the decoded bytes, lowercase hex</td></tr><tr><td><code>data</code></td><td>string</td><td>yes</td><td>format base64; encoding base64</td><td>The image, base64-encoded</td></tr></tbody></table><h2 id="announcement" tabindex="-1">Announcement <a class="header-anchor" href="#announcement" aria-label="Permalink to &quot;Announcement&quot;">​</a></h2><p>An out-of-game announcement from the admin.</p><ul><li><strong>Location:</strong> One item of PubSub node <code>announcements</code></li><li><strong>Access:</strong> Read: every role. Publish: admin.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>text</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 2000</td><td>Plain text</td></tr><tr><td><code>postedAt</code></td><td>string</td><td>yes</td><td>format date-time</td><td>Admin&#39;s clock when posted; display only</td></tr></tbody></table><h2 id="deleted-force-or-role" tabindex="-1">Deleted force or role <a class="header-anchor" href="#deleted-force-or-role" aria-label="Permalink to &quot;Deleted force or role&quot;">​</a></h2><p>The last name of a deleted force or role.</p><ul><li><strong>Location:</strong> One item of PubSub node <code>retired</code>, the item id the entity’s GUID</li><li><strong>Access:</strong> Read: all game users. Publish: admin. Never used to decide access.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>The deleted force or role GUID; also the item id</td></tr><tr><td><code>kind</code></td><td>enum</td><td>yes</td><td>one of &quot;force&quot;, &quot;role&quot;</td><td></td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 120</td><td>Its last display name</td></tr><tr><td><code>loginName</code></td><td>string</td><td>no</td><td>length ≥ 1; length ≤ 64; pattern <code>^[a-z0-9]+(?:-[a-z0-9]+)*$</code></td><td>A role’s login name, which no other role may take (§3 rule 1)</td></tr><tr><td><code>colour</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>The force’s colour, or a role’s force’s colour when it was deleted</td></tr><tr><td><code>deletedAt</code></td><td>string</td><td>yes</td><td>format date-time</td><td>Admin&#39;s clock when the deletion was recorded</td></tr></tbody></table><h2 id="directory" tabindex="-1">Directory <a class="header-anchor" href="#directory" aria-label="Permalink to &quot;Directory&quot;">​</a></h2><p>Where each entity document is, by GUID, and each role by login name.</p><ul><li><strong>Location:</strong> PubSub node <code>directory</code>, one item <code>current</code></li><li><strong>Access:</strong> Read: every role. Publish: admin. A role finds its own role document from its login name here; the role document decides.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>roles</code></td><td>array of object</td><td>yes</td><td></td><td>Every role: its GUID and its login name</td></tr><tr><td><code>roles[]</code></td><td>object</td><td>yes</td><td></td><td></td></tr><tr><td><code>roles[].id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>The role GUID</td></tr><tr><td><code>roles[].loginName</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 64; pattern <code>^[a-z0-9]+(?:-[a-z0-9]+)*$</code></td><td>Login name: the role&#39;s XMPP account name, readable, fixed once published (§3 rule 1, ADM-5)</td></tr><tr><td><code>forces</code></td><td>array of string</td><td>yes</td><td></td><td>Every force GUID</td></tr><tr><td><code>rooms</code></td><td>array of string</td><td>yes</td><td></td><td>Every room GUID</td></tr></tbody></table><h2 id="message-template" tabindex="-1">Message template <a class="header-anchor" href="#message-template" aria-label="Permalink to &quot;Message template&quot;">​</a></h2><p>A message template: a JSON Schema form the admin designs.</p><ul><li><strong>Location:</strong> One item of PubSub node <code>templates</code>, the item id the template’s GUID</li><li><strong>Access:</strong> Read: every role. Publish: admin. Its schema is fixed once a published room offers it (<code>lockedAt</code>).</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>The template GUID; also the item id</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 120</td><td>Shown in the composer’s drop-down and on each card (TD7)</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>length ≤ 1000</td><td>For the admin and the composer; plain text (PLY-14)</td></tr><tr><td><code>schema</code></td><td>map of any</td><td>yes</td><td></td><td>JSON Schema 2020-12 in the WRX template profile: an object of up to 100 named scalar fields (text with a required maxLength of at most 8,000, or 200 with a pattern; number; integer; yes/no; date; date and time; a drop-down of up to 500 options; a force or role picker marked by x-wrx-picker, with x-wrx-scope and x-wrx-force), linked drop-downs and conditions one level deep (dependencies, if/then/else), and patterns that pass a safe-regex check. No $ref, arrays or nested objects</td></tr><tr><td><code>uiSchema</code></td><td>map of any</td><td>no</td><td></td><td>RJSF UI schema in the WRX template profile: field order, widgets, hints</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>yes</td><td>format date-time</td><td>Admin&#39;s clock when created; display only</td></tr><tr><td><code>lockedAt</code></td><td>string</td><td>no</td><td>format date-time</td><td>Set by the first publish that makes the template available in a room; its schema is then fixed, and changing it means copying it to a new template (TD6, TPL-4)</td></tr></tbody></table><h2 id="game-state" tabindex="-1">Game state <a class="header-anchor" href="#game-state" aria-label="Permalink to &quot;Game state&quot;">​</a></h2><p>The current turn and phase.</p><ul><li><strong>Location:</strong> PubSub node <code>game-state</code>, one item <code>current</code></li><li><strong>Access:</strong> Read: every role. Publish: admin, who advances the turn. A first publish sets turn 1, planning; later publishes leave it alone.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>turn</code></td><td>integer</td><td>yes</td><td>≥ 1; ≤ 10000</td><td>The turn number, from 1</td></tr><tr><td><code>phase</code></td><td>enum</td><td>yes</td><td>one of &quot;planning&quot;, &quot;adjudication&quot;</td><td>Each turn has a planning phase, then an adjudication phase (D7)</td></tr></tbody></table><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Theme: tokens plus optional logo and icon assets.</p><ul><li><strong>Location:</strong> The <code>theme</code> field of game setup, forces and rooms</li><li><strong>Access:</strong> As its owning document.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>tokens</code></td><td>object</td><td>yes</td><td></td><td>Design tokens; an unset token inherits from the game theme, then the default</td></tr><tr><td><code>tokens.primary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>tokens.secondary</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>tokens.background</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>tokens.surface</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>tokens.text</code></td><td>string</td><td>no</td><td>pattern <code>^#[0-9a-fA-F]{6}$</code></td><td>Colour as #rrggbb</td></tr><tr><td><code>tokens.fontFamily</code></td><td>enum</td><td>no</td><td>one of &quot;sans&quot;, &quot;serif&quot;, &quot;mono&quot;</td><td>Bundled font id</td></tr><tr><td><code>logoAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr><tr><td><code>iconAssetId</code></td><td>string</td><td>no</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Id of an <code>assets:&lt;id&gt;</code> node</td></tr></tbody></table><h2 id="chat-message-body" tabindex="-1">Chat message body <a class="header-anchor" href="#chat-message-body" aria-label="Permalink to &quot;Chat message body&quot;">​</a></h2><p>A chat room message.</p><ul><li><strong>Location:</strong> Body of a MUC groupchat message in a chat room</li><li><strong>Access:</strong> Room participants with write access post; all participants read.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>constant</td><td>yes</td><td>= &quot;chat&quot;</td><td></td></tr><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>content</code></td><td>object</td><td>yes</td><td></td><td></td></tr><tr><td><code>content.text</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 8000</td><td>Plain text; rendered without HTML (PLY-14)</td></tr></tbody></table><h2 id="chat-room-config" tabindex="-1">Chat room config <a class="header-anchor" href="#chat-room-config" aria-label="Permalink to &quot;Chat room config&quot;">​</a></h2><p>Chat room config: free text and templates.</p><ul><li><strong>Location:</strong> The <code>config</code> field of a <code>chat</code> room document, version 2; <code>{}</code> (version 1) means free text and no templates</li><li><strong>Access:</strong> As the room document.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 2</td><td></td></tr><tr><td><code>freeText</code></td><td>boolean</td><td>yes</td><td></td><td>Free text allowed beside templates (TD3)</td></tr><tr><td><code>templates</code></td><td>array of object</td><td>yes</td><td></td><td>Template entries per force or role (TD4)</td></tr><tr><td><code>templates[]</code></td><td>object</td><td>yes</td><td></td><td>Templates a force or role may use in a room (TD4, TPL-2)</td></tr><tr><td><code>templates[].kind</code></td><td>enum</td><td>yes</td><td>one of &quot;force&quot;, &quot;role&quot;</td><td></td></tr><tr><td><code>templates[].id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>Force or role GUID</td></tr><tr><td><code>templates[].templateIds</code></td><td>array of string</td><td>yes</td><td></td><td>Templates this force or role may use here; a role entry adds to its force’s</td></tr></tbody></table><h2 id="template-message-body" tabindex="-1">Template message body <a class="header-anchor" href="#template-message-body" aria-label="Permalink to &quot;Template message body&quot;">​</a></h2><p>A templated message.</p><ul><li><strong>Location:</strong> Body of a MUC groupchat message in a chat room</li><li><strong>Access:</strong> Room participants with write access post; every receiving client checks it against the template and the room config.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>constant</td><td>yes</td><td>= &quot;template&quot;</td><td></td></tr><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>content</code></td><td>object</td><td>yes</td><td></td><td></td></tr><tr><td><code>content.templateId</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>The template used</td></tr><tr><td><code>content.values</code></td><td>map of any</td><td>yes</td><td>entries ≤ 100</td><td>Field values by field name; pickers hold GUIDs, never names (TPL-8)</td></tr></tbody></table><h2 id="map-room-config" tabindex="-1">Map room config <a class="header-anchor" href="#map-room-config" aria-label="Permalink to &quot;Map room config&quot;">​</a></h2><p>Map room config: the opening view.</p><ul><li><strong>Location:</strong> The <code>config</code> field of the <code>map</code> room document; <code>{}</code> means the defaults</li><li><strong>Access:</strong> As the room document.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>centre</code></td><td>object</td><td>no</td><td></td><td>Where the map opens; unset, it fits the assets</td></tr><tr><td><code>centre.lat</code></td><td>number</td><td>yes</td><td>≥ -90; ≤ 90</td><td></td></tr><tr><td><code>centre.lon</code></td><td>number</td><td>yes</td><td>≥ -180; ≤ 180</td><td></td></tr><tr><td><code>zoom</code></td><td>integer</td><td>no</td><td>≥ 0; ≤ 22</td><td>The zoom it opens at; unset, it fits the assets</td></tr></tbody></table><h2 id="world-state-message-body" tabindex="-1">World-state message body <a class="header-anchor" href="#world-state-message-body" aria-label="Permalink to &quot;World-state message body&quot;">​</a></h2><p>A world-state message in the map room, posted by the admin only.</p><ul><li><strong>Location:</strong> Body of a MUC groupchat message in the map room, up to 500,000 bytes as a stanza; every message carries the full state</li><li><strong>Access:</strong> Every role reads the map room. Clients accept it only from the admin’s real JID and ignore any other sender.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>constant</td><td>yes</td><td>= &quot;world-state&quot;</td><td></td></tr><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>content</code></td><td>object</td><td>yes</td><td></td><td>The full world state: every asset with its position and status (D25)</td></tr><tr><td><code>content.turn</code></td><td>integer</td><td>yes</td><td>≥ 1; ≤ 10000</td><td>The turn this state belongs to</td></tr><tr><td><code>content.assets</code></td><td>map of object</td><td>yes</td><td>entries ≤ 5000</td><td>Every asset, keyed by its GUID; each key is its asset’s <code>id</code> (JSON Schema cannot say so: zod and the Python SDK check it)</td></tr></tbody></table><h2 id="world-state-asset" tabindex="-1">World-state asset <a class="header-anchor" href="#world-state-asset" aria-label="Permalink to &quot;World-state asset&quot;">​</a></h2><p>A unit or platform on the map, with the fixed fields of v1 (§3 rule 17).</p><ul><li><strong>Location:</strong> Each value of <code>content.assets</code> in a world-state message, keyed by its <code>id</code></li><li><strong>Access:</strong> As the world-state message.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>The asset GUID; also its key in <code>assets</code> (§3 rules 1, 16)</td></tr><tr><td><code>forceId</code></td><td>string</td><td>yes</td><td>pattern <code>^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$</code></td><td>The force that owns the asset</td></tr><tr><td><code>title</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 120</td><td>Display name, e.g. &quot;1st Armoured Squadron&quot;</td></tr><tr><td><code>category</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 60</td><td>What kind of asset it is, e.g. &quot;armour&quot; or &quot;frigate&quot;</td></tr><tr><td><code>sidc</code></td><td>string</td><td>yes</td><td>pattern <code>^(?:[SGWIOE][PUAFNSHGWMDLJK*-][A-Z*-][APCDXF*-][A-Z0-9*-]{8}[A-Z*-]{3}|[0-9]{20}|[0-9]{30})$</code></td><td>MIL-STD-2525/APP-6 symbol identification code (SIDC): 15 letter-based characters (2525C, APP-6 B/C) or 20 or 30 digits (2525D/E, APP-6 D)</td></tr><tr><td><code>lat</code></td><td>number</td><td>yes</td><td>≥ -90; ≤ 90</td><td>Latitude, WGS 84 decimal degrees</td></tr><tr><td><code>lon</code></td><td>number</td><td>yes</td><td>≥ -180; ≤ 180</td><td>Longitude, WGS 84 decimal degrees</td></tr><tr><td><code>state</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 60</td><td>Its condition in words, e.g. &quot;operational&quot; or &quot;damaged&quot;</td></tr><tr><td><code>health</code></td><td>number</td><td>yes</td><td>≥ 0; ≤ 100</td><td>Health, 0 (destroyed) to 100 (full)</td></tr><tr><td><code>fuel</code></td><td>number</td><td>yes</td><td>≥ 0; ≤ 100</td><td>Fuel, 0 (empty) to 100 (full)</td></tr></tbody></table><h2 id="umpire-room-config" tabindex="-1">Umpire room config <a class="header-anchor" href="#umpire-room-config" aria-label="Permalink to &quot;Umpire room config&quot;">​</a></h2><p>Umpire room config: nothing to set.</p><ul><li><strong>Location:</strong> The <code>config</code> field of the <code>umpire</code> room document; nothing to set, <code>{}</code> reads as version 1</li><li><strong>Access:</strong> As the room document. The room’s participants are fixed: the White Force, plus a read entry for each White Force observer assigned rooms elsewhere (§3 rule 18).</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr></tbody></table><h2 id="white-force-proposal-message-body" tabindex="-1">White Force proposal message body <a class="header-anchor" href="#white-force-proposal-message-body" aria-label="Permalink to &quot;White Force proposal message body&quot;">​</a></h2><p>A White Force proposal in the umpire room (PY-8).</p><ul><li><strong>Location:</strong> Body of a MUC groupchat message in the umpire room, up to 500,000 bytes as a stanza; carries a full world state and a summary</li><li><strong>Access:</strong> The admin and the White Force read the umpire room; its roles that are not observers post. Clients accept it only in the umpire room and only from the admin or a White Force role; the admin may load it into the world-state draft (PY-8).</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>constant</td><td>yes</td><td>= &quot;world-proposal&quot;</td><td></td></tr><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 1</td><td></td></tr><tr><td><code>content</code></td><td>object</td><td>yes</td><td></td><td>A proposed world state and its summary</td></tr><tr><td><code>content.state</code></td><td>object</td><td>yes</td><td></td><td>The proposed world state, in full (D25)</td></tr><tr><td><code>content.summary</code></td><td>string</td><td>yes</td><td>length ≥ 1; length ≤ 2000</td><td>What the proposal changes, in words, for the admin; plain text</td></tr></tbody></table><h2 id="design-file" tabindex="-1">Design file <a class="header-anchor" href="#design-file" aria-label="Permalink to &quot;Design file&quot;">​</a></h2><p>A complete game design, as exported and imported by the admin.</p><ul><li><strong>Location:</strong> A JSON file the admin exports and imports</li><li><strong>Access:</strong> Held by the admin. Never contains passwords.</li></ul><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Rules</th><th>Description</th></tr></thead><tbody><tr><td><code>format</code></td><td>constant</td><td>yes</td><td>= &quot;wrx1-design&quot;</td><td></td></tr><tr><td><code>schemaVersion</code></td><td>constant</td><td>yes</td><td>= 3</td><td></td></tr><tr><td><code>exportedAt</code></td><td>string</td><td>yes</td><td>format date-time</td><td>ISO 8601 date-time</td></tr><tr><td><code>game</code></td><td>object</td><td>yes</td><td></td><td>The game setup document</td></tr><tr><td><code>forces</code></td><td>array of object</td><td>yes</td><td></td><td>Force documents</td></tr><tr><td><code>roles</code></td><td>array of object</td><td>yes</td><td></td><td>Role documents; a <code>password</code> field is rejected</td></tr><tr><td><code>rooms</code></td><td>array of object</td><td>yes</td><td></td><td>Room documents</td></tr><tr><td><code>objectives</code></td><td>array of object</td><td>yes</td><td></td><td>Objectives documents, at most one per force</td></tr><tr><td><code>assets</code></td><td>array of object</td><td>yes</td><td></td><td>Asset documents</td></tr><tr><td><code>retired</code></td><td>array of object</td><td>yes</td><td></td><td>The last names of deleted forces and roles that were published, kept so old messages show them (§3 rule 1)</td></tr><tr><td><code>templates</code></td><td>array of object</td><td>yes</td><td></td><td>Message templates (Annex A); a file from before templates has none. Each locks when a published room makes it available (TPL-4)</td></tr><tr><td><code>worldState</code></td><td>object</td><td>no</td><td></td><td>The world state to set the map up with (ADM-16): the admin’s draft when exported, else the latest published state. Imported as the admin’s draft, published only by the admin (ADM-45)</td></tr></tbody></table>',87)])])}const g=d(a,[["render",s]]);export{u as __pageData,g as default};
